# -*- coding: utf-8 -*-
"""Round52 QA garble-fix patch (items + lessons). Idempotent-ish: skips missing old strings."""

def patch(fn, pairs):
    txt = open(fn, encoding='utf-8').read()
    miss, applied = [], 0
    for old, new in pairs:
        if old not in txt:
            miss.append(old[:80])
        else:
            txt = txt.replace(old, new); applied += 1
    open(fn, 'w', encoding='utf-8').write(txt)
    print(fn, 'applied:', applied, 'misses:', len(miss))
    for m in miss:
        print('  MISS:', m)

